css:
@font-face {
    font-family: Calibri;
    src: url('/files/Calibri.ttf');
}

.print-format {
    font-family: Calibri;
    font-size: 12pt;
    box-sizing: border-box !important;
}

/* Ensure padding adjustments never blow out layout box boundaries */
.print-format *, .print-format *::before, .print-format *::after {
    box-sizing: border-box !important;
}

p {
    width: 99%;
}

.ql-editor {
    font-family: Calibri !important;
    font-size: 12pt !important;
    line-height: 1.2 !important;
}

/* --- STREAMLINED: Side-by-Side Flex Header Layout Fix --- */
.header-flex-container {
    display: flex !important;
    flex-direction: row !important;
    justify-content: space-between !important;
    align-items: flex-start !important;
    width: 100% !important;
    margin-bottom: 25px;
}

.header-logo-img {
    max-width: 50% !important;
    width: 7.28cm !important;
    height: 2.81cm !important;
    object-fit: contain !important;
}

.header-address {
    text-align: right !important; 
    max-width: 45% !important;
    line-height: 1.1;
}

p.standard-para {
    margin-top: 1em;
}

div.alignment-heading {
    margin-top: 1em;
    float: left;
    display: inline-block;
    vertical-align: text-top;
    width: 230px !important;
}

div.alignment-value {
    margin-top: 1em;
    display: inline-block;
    width: 300px !important;
}

div.alignment-cost-heading {
    text-align: right;
    display: inline-block;
    width: 400px !important;
    line-height: 1.2;
}

div.alignment-cost-value {
    text-align: right;
    display: inline-block;
    width: 200px !important;
}

div.section-heading {
    margin-top: 1em;
    font-style: italic;
}

div.standard-heading {
    margin-top: 1em;
}

div.first-line-date {
    margin-top: 4em;
    margin-bottom: 2em;
    display: inline-block;
    width: 400px;
}

div.first-line-quote {
    margin-top: 4em;
    margin-bottom: 2em;
    display: inline-block;
    float: right;
}

div.address {
    margin-bottom: 3em;
    line-height: 1.1;
    clear: both;
}

div.signature-top {
    margin-top: 1em;
}

div.signature {
    display: table-cell;
    vertical-align: middle;
}

div.customer-sig {
    margin-top: 2.5em;
}

hr.solid {
    border-top: 1px solid black;
}

/* Fallback isolation rules for inline user grid elements */
.print-format table:not(.print-table) {
   width: 100%;
   border: none;
}

.print-format td:not(.print-layout-cell) {
   width: 100%;
}

/* Advanced Paged Media layout properties for Chromium printing */
@media print {
    html, body { margin: 0; padding: 0; background-color: #fff; }
    .print-table { width: 100%; border-collapse: collapse; border: none !important; }
    .print-layout-cell { width: 100%; border: none !important; padding: 0; }
    .print-footer-space { height: 40mm; }
    .print-footer { 
        position: fixed; bottom: 0; left: 0; right: 0; height: 35mm; 
        border-top: 1px solid #e2e8f0; padding-top: 15px; background-color: #fff; 
    }
    .page-break { page-break-before: always; display: block !important; }
    .section-break, p, tr, li, .address, .signature-top, .signature-section { page-break-inside: avoid !important; }
}
@media screen {
    .print-table { width: 100%; border-collapse: collapse; }
    .print-footer { margin-top: 50px; border-top: 1px solid #e2e8f0; padding-top: 15px; }
}
.letter-head-footer-flex { display: flex; align-items: center; justify-content: flex-start; gap: 15px; }
.slogan-text { font-style: italic; color: #555; }
